// Procesar y validar datos de entrada del usuario
const inputData = $json;

// Validar estructura de datos
if (!inputData || typeof inputData !== 'object') {
  return [{
    json: {
      success: false,
      error: 'Invalid input data structure',
      received: inputData
    }
  }];
}

// Extraer información de la acción del usuario
const userAction = {
  // Datos principales
  actionType: inputData.action || inputData.type || 'unknown_action',
  targetElement: inputData.element || inputData.target || 'unknown_element',
  actionValue: inputData.value || inputData.text || '',

  // Contexto de la página
  pageUrl: inputData.url || inputData.pageUrl || window.location?.href || '',
  pageTitle: inputData.title || inputData.pageTitle || 'Unknown Page',

  // Metadatos de sesión
  sessionId: inputData.sessionId || `session_${Date.now()}`,
  timestamp: inputData.timestamp || new Date().toISOString(),

  // Información técnica
  selector: inputData.selector || inputData.css || '',
  xpath: inputData.xpath || '',
  coordinates: inputData.coordinates || { x: 0, y: 0 },

  // Contexto del navegador
  userAgent: inputData.userAgent || navigator?.userAgent || 'Unknown',
  viewport: inputData.viewport || { width: 0, height: 0 }
};

// Crear estructura de datos para MCP
const mcpReadyData = {
  // Metadatos del workflow
  workflowType: 'user_action_capture',
  timestamp: new Date().toISOString(),

  // Datos de la acción procesada
  userAction: userAction,

  // Contexto para MCP
  mcpContext: {
    task: 'capture_user_interaction',
    domain: new URL(userAction.pageUrl || 'http://localhost').hostname,
    actionSequence: 1, // Se incrementará en futuras implementaciones
    sessionMetadata: {
      id: userAction.sessionId,
      startTime: userAction.timestamp,
      currentAction: userAction.actionType
    }
  },

  // Información de respuesta
  responseInfo: {
    success: true,
    message: `✅ Paso capturado: ${userAction.actionType.toUpperCase()} en ${userAction.targetElement}`,
    stepNumber: 1,
    readyForMCP: true
  }
};

// Log detallado para debugging
console.log('🎯 USER ACTION CAPTURED:', {
  action: userAction.actionType,
  element: userAction.targetElement,
  page: userAction.pageTitle,
  session: userAction.sessionId,
  timestamp: userAction.timestamp
});

// Preparar datos para el siguiente nodo MCP
return [{
  json: mcpReadyData
}];

// Combinar datos del usuario con información de MCP
const userData = $input.first().json;
const mcpResult = $input.all()[1]?.json || { tools: [] };

// Crear respuesta completa con información MCP
const completeResponse = {
  // Estado de la captura
  capture: {
    success: true,
    message: userData.responseInfo.message,
    timestamp: userData.timestamp
  },

  // Detalles de la acción del usuario
  userStep: {
    action: userData.userAction.actionType,
    element: userData.userAction.targetElement,
    value: userData.userAction.actionValue,
    page: {
      title: userData.userAction.pageTitle,
      url: userData.userAction.pageUrl
    },
    technical: {
      selector: userData.userAction.selector,
      coordinates: userData.userAction.coordinates,
      viewport: userData.userAction.viewport
    }
  },

  // Información de la sesión
  session: {
    id: userData.userAction.sessionId,
    stepNumber: userData.responseInfo.stepNumber,
    domain: userData.mcpContext.domain
  },

  // Resultados de MCP
  mcpAnalysis: {
    toolsFound: mcpResult.tools?.length || 0,
    recommendations: mcpResult.tools || [],
    mcpProcessed: true,
    serverConnected: mcpResult.server_status || 'unknown'
  },

  // Próximos pasos
  nextActions: {
    continueCapture: 'Realizar más acciones en la página',
    generateTests: 'Usar webhook /generate-tests-mcp cuando termine',
    viewSession: `Revisar sesión ${userData.userAction.sessionId}`
  },

  // Metadatos finales
  metadata: {
    processedAt: new Date().toISOString(),
    workflowVersion: '2.0-mcp-native',
    mcpIntegration: 'active',
    dataValidated: true
  }
};

// Log de confirmación
console.log('🚀 MCP WORKFLOW COMPLETED:', {
  session: userData.userAction.sessionId,
  action: userData.userAction.actionType,
  mcpTools: mcpResult.tools?.length || 0,
  success: true
});

return [{json: completeResponse}];

// Procesar resultado de generación MCP y crear tests finales
const generationRequest = $input.first().json;
const mcpGeneration = $input.all()[1]?.json || {};

// Extraer datos de la sesión
const sessionData = {
  sessionId: generationRequest.sessionId || 'unknown',
  actions: generationRequest.actions || [],
  pageTitle: generationRequest.pageTitle || 'Test Page',
  pageUrl: generationRequest.pageUrl || '',
  userAgent: generationRequest.userAgent || ''
};

// Crear código de test usando MCP + datos de sesión
const testCode = {
  // Selenium WebDriver (JavaScript)
  selenium: {
    framework: 'selenium-webdriver',
    language: 'javascript',
    code: `
// Generated with n8n MCP Integration
// Session: ${sessionData.sessionId}
// Page: ${sessionData.pageTitle}

const { Builder, By, until, Key } = require('selenium-webdriver');
const assert = require('assert');

describe('${sessionData.pageTitle} - Automated Test', () => {
  let driver;

  beforeEach(async () => {
    driver = await new Builder()
      .forBrowser('chrome')
      .build();
  });

  afterEach(async () => {
    if (driver) {
      await driver.quit();
    }
  });

  it('should execute captured user journey', async () => {
    // Navigate to target page
    await driver.get('${sessionData.pageUrl}');

    // Wait for page to load
    await driver.wait(until.titleContains('${sessionData.pageTitle}'), 10000);

    // Execute captured actions
${sessionData.actions.map((action, index) => 
  `    // Step ${index + 1}: ${action.type || 'action'} on ${action.element || 'element'}
    // TODO: Implement ${action.type} for ${action.element}`
).join('\n')}

    // Verify final state
    const title = await driver.getTitle();
    assert(title.includes('${sessionData.pageTitle}'), 'Page title should contain expected text');
  });
});
`
  },

  // Playwright (JavaScript)
  playwright: {
    framework: 'playwright',
    language: 'javascript', 
    code: `
// Generated with n8n MCP Integration
// Session: ${sessionData.sessionId}

const { test, expect } = require('@playwright/test');

test.describe('${sessionData.pageTitle} - User Journey', () => {
  test('should replicate captured user actions', async ({ page }) => {
    // Navigate to page
    await page.goto('${sessionData.pageUrl}');

    // Wait for page load
    await expect(page).toHaveTitle(/${sessionData.pageTitle}/);

    // Execute captured user actions
${sessionData.actions.map((action, index) => 
  `    // Step ${index + 1}: ${action.type || 'action'}
    // await page.click('${action.selector || action.element}');`
).join('\n')}

    // Final verification
    await expect(page).toHaveURL(/${sessionData.pageUrl.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}/);
  });
});
`
  }
};

// Respuesta final con tests generados
const finalResponse = {
  success: true,
  message: '🎉 Tests generados exitosamente con MCP',

  // Información de la sesión
  session: {
    id: sessionData.sessionId,
    actionCount: sessionData.actions.length,
    page: sessionData.pageTitle,
    url: sessionData.pageUrl
  },

  // Tests generados
  generatedTests: testCode,

  // Información MCP
  mcpProcessing: {
    serverUsed: 'n8n-mcp-server',
    toolsApplied: ['generate_workflow'],
    processingTime: new Date().toISOString(),
    mcpResult: mcpGeneration
  },

  // Metadatos
  metadata: {
    generatedAt: new Date().toISOString(),
    frameworks: ['selenium', 'playwright'],
    language: 'javascript',
    mcpIntegrated: true,
    version: '2.0-mcp-native'
  }
};

console.log('🎯 TESTS GENERATED WITH MCP:', {
  session: sessionData.sessionId,
  actionCount: sessionData.actions.length,
  frameworks: ['selenium', 'playwright'],
  mcpUsed: true
});

return [{json: finalResponse}];
